begin;
set local lock_timeout='5s';set local statement_timeout='30s';set local standard_conforming_strings=on;
create temporary table reviewed_plan(payload jsonb) on commit drop;
insert into reviewed_plan values('[{"id":4903,"sku":"6365C002","brand":"Canon","name":"Картридж Canon 075 MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw Black (1400 стор.) (6365C002)","source":"https://www.canon.co.uk/store/store/canon-075-black-toner-cartridge/6365C002/","protectDescription":false,"before":{"specifications":{},"description":"~1400 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, чорний","manual_overrides":{}},"after":{"specifications":{"Тип витратного матеріалу":"Тонер-картридж","Серія картриджа":"075","Колір друку":"Чорний","Ресурс друку":"До 1400 сторінок","Ємність картриджа":"Стандартна","Сумісний бренд":"Canon","Сумісні пристрої":"Canon i-SENSYS MF664Cdw; MF667Cdw; LBP646Cdw; LBP647Cdw"},"description":"~1400 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, чорний","manual_overrides":{"verified_specifications":true}}},{"id":4904,"sku":"6364C002","brand":"Canon","name":"Картридж Canon 075C MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw Cyan (1300 стор.) (6364C002)","source":"https://www.canon.co.uk/store/canon-075-cyan-toner-cartridge/6364C002/","protectDescription":false,"before":{"specifications":{},"description":"~1300 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, блакитний","manual_overrides":{}},"after":{"specifications":{"Тип витратного матеріалу":"Тонер-картридж","Серія картриджа":"075","Колір друку":"Блакитний (Cyan)","Ресурс друку":"До 1300 сторінок","Ємність картриджа":"Стандартна","Сумісний бренд":"Canon","Сумісні пристрої":"Canon i-SENSYS MF664Cdw; MF667Cdw; LBP646Cdw; LBP647Cdw"},"description":"~1300 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, блакитний","manual_overrides":{"verified_specifications":true}}},{"id":4905,"sku":"6369C002","brand":"Canon","name":"Картридж Canon 075H MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw Black (3500 стор.) (6369C002)","source":"https://www.canon.co.uk/store/canon-075-h-high-yield-black-toner-cartridge/6369C002/","protectDescription":false,"before":{"specifications":{},"description":"~3500 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, чорний","manual_overrides":{}},"after":{"specifications":{"Тип витратного матеріалу":"Тонер-картридж","Серія картриджа":"075H","Колір друку":"Чорний","Ресурс друку":"До 3500 сторінок","Ємність картриджа":"Підвищена","Сумісний бренд":"Canon","Сумісні пристрої":"Canon i-SENSYS MF664Cdw; MF667Cdw; LBP646Cdw; LBP647Cdw"},"description":"~3500 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, чорний","manual_overrides":{"verified_specifications":true}}},{"id":4906,"sku":"6368C002","brand":"Canon","name":"Картридж Canon 075H MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw Cyan (2500 стор.) (6368C002)","source":"https://www.canon.co.uk/store/canon-075-h-high-yield-cyan-toner-cartridge/6368C002/","protectDescription":false,"before":{"specifications":{},"description":"~2500 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, блакитний","manual_overrides":{}},"after":{"specifications":{"Тип витратного матеріалу":"Тонер-картридж","Серія картриджа":"075H","Колір друку":"Блакитний (Cyan)","Ресурс друку":"До 2500 сторінок","Ємність картриджа":"Підвищена","Сумісний бренд":"Canon","Сумісні пристрої":"Canon i-SENSYS MF664Cdw; MF667Cdw; LBP646Cdw; LBP647Cdw"},"description":"~2500 стор. @5% (A4) для MF664Cdw/MF667Cdw/LBP646Cdw/LBP647Cdw, блакитний","manual_overrides":{"verified_specifications":true}}}]'::jsonb);
do $reviewed$
declare item jsonb;before_row jsonb;after_row jsonb;
begin
 if not(select relrowsecurity from pg_class where oid='technoroom_maintenance.product_repair_backup'::regclass) then raise exception 'Protected backup required';end if;
 if (select jsonb_array_length(payload) from reviewed_plan)<>4 then raise exception 'Unexpected plan size';end if;
 perform id from public.products where id in (4903,4904,4905,4906) order by id for update;
 for item in select value from reviewed_plan,jsonb_array_elements(payload) loop
  select to_jsonb(p) into before_row from public.products p where id=(item->>'id')::bigint;
  if before_row is null or before_row->>'sku' is distinct from item->>'sku' or before_row->>'brand' is distinct from item->>'brand' or before_row->>'name' is distinct from item->>'name' then raise exception 'Identity changed';end if;
  if before_row->'specifications' is distinct from item->'before'->'specifications' or before_row->'description' is distinct from item->'before'->'description' or before_row->'manual_overrides' is distinct from item->'before'->'manual_overrides' then raise exception 'Card changed after preview';end if;
  if exists(select 1 from technoroom_maintenance.product_repair_backup where operation='canon-075-content-20261027' and product_id=(item->>'id')::bigint) then raise exception 'Already backed up; verify before retry';end if;
  insert into technoroom_maintenance.product_repair_backup(operation,product_id,before_row,backed_up_at) values('canon-075-content-20261027',(item->>'id')::bigint,before_row,now());
  insert into technoroom_maintenance.reviewed_product_content(product_id,sku,brand,source,protect_description,operation) values((item->>'id')::bigint,item->>'sku',item->>'brand',item->>'source',(item->>'protectDescription')::boolean,'canon-075-content-20261027');
  -- A maintenance/manual write, never an importer write.
  perform set_config('technoroom.import_write','false',true);
  update public.products set specifications=item->'after'->'specifications' where id=(item->>'id')::bigint;
  select to_jsonb(p) into after_row from public.products p where id=(item->>'id')::bigint;
  if after_row->'specifications' is distinct from item->'after'->'specifications' or after_row->'description' is distinct from before_row->'description' or (after_row-array['specifications','manual_overrides','updated_at']) is distinct from (before_row-array['specifications','manual_overrides','updated_at']) or after_row->'manual_overrides' is distinct from item->'after'->'manual_overrides' then raise exception 'Unexpected side effect';end if;
 end loop;
end $reviewed$;
commit;
